let lang = "pt";

const texts = {
    en: {
        title: "🌍 Nationalities",
        question: "In which country were you born?",
        placeholder: "Type a country",
        button: "Verify",
        error: "Country not found. Try another spelling, or pick one from the suggestions.",
        empty: "Type a country name above 🙂",
        capital: "Capital",
        language: "Language",
        currency: "Currency",
        population: "Population",
        continent: "Continent",
        drive: "Drive on the",
        left: "left",
        right: "right",
        na: "N/A"
    },
    pt: {
        title: "🌍 Nacionalidades",
        question: "Em qual país você nasceu?",
        placeholder: "Digite um país",
        button: "Verificar",
        error: "País não encontrado. Tente outra grafia, ou escolha uma das sugestões.",
        empty: "Digite o nome de um país acima 🙂",
        capital: "Capital",
        language: "Idioma",
        currency: "Moeda",
        population: "População",
        continent: "Continente",
        drive: "Dirige-se pela",
        left: "esquerda",
        right: "direita",
        na: "N/A"
    }
};

function normalize(str) {
    return String(str)
        .normalize('NFD')
        .replace(/[̀-ͯ]/g, '')
        .toLowerCase()
        .trim();
}

// Aliases/abbreviations that don't match a country's own name
const ALIASES = {
    'usa': 'United States', 'eua': 'United States', 'us': 'United States', 'america': 'United States',
    'uk': 'United Kingdom', 'reino unido': 'United Kingdom', 'inglaterra': 'United Kingdom', 'england': 'United Kingdom',
    'uae': 'United Arab Emirates', 'emirados arabes': 'United Arab Emirates', 'emirados arabes unidos': 'United Arab Emirates',
    'holanda': 'Netherlands',
    'coreia do sul': 'South Korea', 'coreia do norte': 'North Korea', 'korea': 'South Korea',
    'republica tcheca': 'Czechia', 'czech republic': 'Czechia',
    'costa do marfim': 'Ivory Coast',
    'russia': 'Russia', 'russian federation': 'Russia',
};

let byNormalizedName = {};
let allNames = [];

function buildIndex() {
    byNormalizedName = {};
    allNames = [];
    COUNTRIES_DATA.forEach(c => {
        byNormalizedName[normalize(c.en)] = c;
        byNormalizedName[normalize(c.pt)] = c;
    });
    Object.entries(ALIASES).forEach(([alias, enName]) => {
        const target = COUNTRIES_DATA.find(c => c.en === enName);
        if (target) byNormalizedName[normalize(alias)] = target;
    });
}

function findCountry(query) {
    const key = normalize(query);
    if (!key) return null;
    if (byNormalizedName[key]) return byNormalizedName[key];

    const starts = COUNTRIES_DATA.find(c => normalize(c.en).startsWith(key) || normalize(c.pt).startsWith(key));
    if (starts) return starts;

    const contains = COUNTRIES_DATA.find(c => normalize(c.en).includes(key) || normalize(c.pt).includes(key));
    return contains || null;
}

function refreshDatalist() {
    const list = document.getElementById('countries-list');
    list.innerHTML = '';
    const names = COUNTRIES_DATA
        .map(c => lang === 'pt' ? c.pt : c.en)
        .sort((a, b) => a.localeCompare(b, lang === 'pt' ? 'pt-BR' : 'en-US'));
    names.forEach(name => {
        const opt = document.createElement('option');
        opt.value = name;
        list.appendChild(opt);
    });
}

function setLang(newLang) {
    lang = newLang;
    document.getElementById('title').innerText = texts[lang].title;
    document.getElementById('question').innerText = texts[lang].question;
    document.getElementById('btn').value = texts[lang].button;
    document.getElementById('txtname').placeholder = texts[lang].placeholder;
    document.getElementById('lang-pt').classList.toggle('active', lang === 'pt');
    document.getElementById('lang-en').classList.toggle('active', lang === 'en');
    refreshDatalist();
}

function showError(message) {
    const res = document.getElementById('ver');
    res.innerHTML = `<div class="error-box">${message}</div>`;
    res.classList.add('show');
}

function verify() {
    const input = document.getElementById('txtname');
    const res = document.getElementById('ver');
    const query = input.value.trim();

    if (!query) {
        showError(texts[lang].empty);
        return;
    }

    const country = findCountry(query);
    if (!country) {
        showError(texts[lang].error);
        return;
    }

    const t = texts[lang];
    const name = lang === 'pt' ? country.pt : country.en;
    const capital = country.capital || t.na;
    const language = country.language || t.na;
    const currency = country.currency ? `${country.currency}${country.currencySymbol ? ' (' + country.currencySymbol + ')' : ''}` : t.na;
    const population = country.population
        ? country.population.toLocaleString(lang === 'pt' ? 'pt-BR' : 'en-US')
        : t.na;
    const continent = country.continent || t.na;
    const drive = country.drivingSide ? (country.drivingSide === 'left' ? t.left : t.right) : t.na;

    const flagUrl = `https://flagcdn.com/h80/${country.cca2.toLowerCase()}.png`;

    res.innerHTML = `
        <div class="result-header">
            <img class="result-flag" src="${flagUrl}" alt="${name}" onerror="this.replaceWith(Object.assign(document.createElement('span'),{className:'result-flag-emoji',textContent:'${country.flagEmoji}'}))">
            <div class="result-name">${name}</div>
        </div>
        <div class="stat-grid">
            <div class="stat-row"><div class="stat-label">🏙️ ${t.capital}</div><div class="stat-value">${capital}</div></div>
            <div class="stat-row"><div class="stat-label">🗣️ ${t.language}</div><div class="stat-value">${language}</div></div>
            <div class="stat-row"><div class="stat-label">💰 ${t.currency}</div><div class="stat-value">${currency}</div></div>
            <div class="stat-row"><div class="stat-label">👥 ${t.population}</div><div class="stat-value">${population}</div></div>
            <div class="stat-row"><div class="stat-label">🌎 ${t.continent}</div><div class="stat-value">${continent}</div></div>
            <div class="stat-row"><div class="stat-label">🚗 ${t.drive}</div><div class="stat-value">${drive}</div></div>
        </div>
    `;
    res.classList.add('show');
}

buildIndex();
refreshDatalist();
